For real sequences $\{a_t\}$ and $\{b_t\}$, we write $a_t = O(b_t)$ if there exist constants $C,N>0$ such that $a_t \le Cb_t$ for all $t \ge N$; 
$a_t = \Omega(b_t)$ if $b_t = O(a_t)$; 
$a_t = \Theta(b_t)$ if both $a_t = O(b_t)$ and $a_t = \Omega(b_t)$; 
and we use $\tilde{O}(\cdot)$ and $\tilde{\Omega}(\cdot)$ to suppress logarithmic factors.

Formally, the goal is to minimize the loss:
\begin{align}\label{eq:opt}
    \min_{\Wb \in \RR^{m\times n}} 
    F(\Wb) = \EE_{\bxi}[f(\Wb; \bxi)],
\end{align}
where $\Wb$ denotes the model parameters, $\bxi$ is a random variable representing the data, and $f(\Wb;\bxi)$ is the sample loss. 
We denote $F^* = \inf_{\Wb} F(\Wb) > -\infty$ as the optimal objective value.

\begin{align*}
q_W &:= \inf\big\{q \ge 0 : |[\Wb_t^Q]_{ij} - [\Wb_t]_{ij}| \le q |[\Wb_t]_{ij}|, \forall t\big\},\\
q_G &:= \inf\big\{q \ge 0 : |[\Gb_t^Q]_{ij} - [\Gb_t]_{ij}| \le q |[\Gb_t]_{ij}|, \forall t\big\},\\
q_M &:= \inf\big\{q \ge 0 : |[\Mb_t^Q]_{ij} - [\Mb_t]_{ij}| \le q |[\Mb_t]_{ij}|, \forall t\big\},\\
q_V &:= \inf\big\{q \ge 0 : |[\Vb_t^Q]_{ij} - [\Vb_t]_{ij}| \le q |[\Vb_t]]_{ij}|, \forall t\big\}.
\end{align*}

\caption{Analytical Adaptive Method Quantization Training Framework}
\label{alg:framework}
\begin{algorithmic}[1]
    \State \textbf{Input 1}: Algorithm $\cA\in \{\mathrm{Adam},\mathrm{Muon} \}$ and its parameters set $\bTheta \in \{\{ \beta_1,\beta_2,\epsilon \},\{\beta \} \}$, initial weights $\Wb_0$, learning rate schedule $\{\eta_t\}$, batch size $B$, quantization operator $\cQ$
    \For{$t = 0, \ldots, T-1$}
        \State Sample batch $\{\bxi_{t,i}\}_{i=1}^B$ uniformly \Comment{$B$ workers}
        \State $\Gb_t = \frac{1}{B} \sum_{i=1}^B \nabla^Q f(\Wb_t^Q; \bxi_{t,i})$ \Comment{Master receives $B$ quantized gradients}
        \State $\Wb_{t+1} = \cA(\Wb_t, \Gb_t, \bTheta, t)$ \Comment{Update by Adam or Muon}
    \EndFor
\end{algorithmic}

\label{assump:grad_bounds}
    The stochastic gradient $\nabla f(\Wb;\bxi)$ satisfies the following bounds depending on the algorithm:
    \begin{itemize}[leftmargin=*]
        \item {\bf Adam}: The stochastic gradient is $\ell_\infty$ uniformly almost surely bounded, i.e., there exists a constant $R > \sqrt{\epsilon}$ (where $\epsilon > 0$ is the stability constant used to simplify the final bounds) such that
        \begin{align*}
            \|\nabla f(\Wb;\bxi)\|_\infty = \max_{i,j} |[\nabla f(\Wb;\bxi)]_{ij}| \le R - \sqrt{\epsilon}, \quad \text{a.s.}.
        \end{align*}
        \item {\bf Muon}: The stochastic gradient has bounded variance, i.e., there exists a constant $\sigma > 0$ such that
        \begin{align*}
            \EE[\|\nabla f(\Wb;\bxi) - \nabla F(\Wb)\|_F^2] \le \sigma^2.
        \end{align*}
    \end{itemize}

\label{assump:smooth}
    The objective function $F:\RR^{m\times n}\to\RR$ is $L$-smooth, i.e., for any $\Xb, \Yb \in \RR^{m\times n}$, we have
    \begin{align*}
    \|\nabla F(\Xb) - \nabla F(\Yb)\|_F \;\le\; L \|\Xb - \Yb\|_F.
    \end{align*}

\label{thm:QAdam}
Suppose Assumptions~\ref{assump:qe},~\ref{assump:grad_unbiased}–\ref{assump:bound_init} hold. Let $d=mn$ be the number of trainable parameters, consider the Quantized Adam algorithm defined in \ref{alg:framework} run for $T$ iterations with $\eta_t = (1 - \beta_1) \Omega_t \eta$, where $\Omega_t = \sqrt{\sum_{j=0}^{t-1} \beta_2^j}$. Suppose $\beta_1^2(1+q_M)^2 < \beta_2(1-q_V)$, $\beta_1(1+q_M) < \beta_2(1-q_V)$, and $2\beta_1/(1-\beta_1)\le T$, then for an iteration index $\tau$ chosen randomly from $\{0, \dots, T-1\}$ with $P(\tau=j) \propto (1 - \beta_1^{T-j})$, we have:

\begin{align*}
\nonumber
    &\esp{\norm{\nabla F(\Wb_{\tau})}_F^2} \leq
    4 (1+q_G)R \frac{F_0 - F_*}{\eta T}+\frac{\tilde{Q}(T)}{T} + \frac{2q_W T\eta\cdot (1-\beta_1)d^\frac{3}{2} \eta  L (1+q_G)R^2 }{\sqrt{\epsilon}(1-\beta_2)\sqrt{1-\frac{\beta_1^2(1+q_M)^2}{\beta_2(1-q_V)}}} \\
    \nonumber
    &+\frac{4(1+q_G) d }{\sqrt{\epsilon(1-\beta_2)}} \left( q_G R^3 + L q_W R^2 D \right) + \frac{C}{T}\left(\ln\left(1 + \frac{((1+q_G)R)^2}{\epsilon(1-\beta_2(1-q_V))}\right) - T\ln(\beta_2(1-q_V))\right) ,
\end{align*}
where $C$ is a constant depending on the problem hyperparameters, and $\tilde Q(T)$ is a function with respect to $T$, $q_V$, $q_G$, and $q_M$, which approaches zero when $q_V, q_M\rightarrow 0$ (please refer to Eq~\ref{eq:all_definitions} for their detailed formula).


Moreover, by setting $\eta=\Theta(1/\sqrt{T})$, $1-\beta_2=\Theta(1/T)$, $q_G = \cO(1/T)$, $q_M = \cO(1/T)$, $q_V = \cO(1/T^2)$, $q_W = \cO(1/T^2)$, then $\tilde Q(T)/T = \cO(T^{-1/2})$ (refer to Eq.~\ref{eq:QT_cal} for calculation details) and
    \begin{align*}
        \EE[\|\nabla F(\Wb_{\tau})\|_F] = \tilde{\cO}\left(T^{-1/4}\right).
    \end{align*}

\label{thm:QMuon}
Suppose Assumptions~\ref{assump:qe},~\ref{assump:grad_unbiased}–\ref{assump:bound_init} hold. Consider the Quantized Muon algorithm in \ref{alg:framework} and~\ref{alg:muon} run for $T$ iterations with $\eta_t=\eta,\beta(1+q_M) < 1$, then
