\label{app:lemma:discrete_error_bound}
Given two discrete-time systems defined for \( t \ge 1 \):
\begin{itemize}
    \item System A: \( a_{t}=k(a_{t-1}+c_{t-1})+d_{t} \)
    \item System B: \( b_{t}=kb_{t-1}+d_{t} \)
\end{itemize}
where the perturbation term \( c_t \) is bounded by \( |c_{t}|\le q|a_{t}| \) for all \( t \), and the constants \( k, q \) satisfy \( 0<k<1 \) and \( q<k \).

Under zero initial conditions, where \( a_0 = b_0 = 0 \), the absolute error between the states of the two systems is bounded by:
\begin{align}
    |a_{t}-b_{t}|\le\sum_{j=1}^{t-1}\left[(k(1+q))^{t-j}-k^{t-j}\right]|d_{j}|
\end{align}

First, define the error as \( e_t = a_t - b_t \). Subtracting the two system equations yields the error recurrence relation:
\begin{align}
    e_{t} = ke_{t-1} + kc_{t-1}
\end{align}
The explicit solution to this recurrence is \( e_{t} = k^{t}e_{0} + \sum_{j=0}^{t-1}k^{t-j}c_{j} \). Under the zero initial condition \( a_0 = b_0 = 0 \), this simplifies to:
\begin{align}
    e_{t} = \sum_{j=0}^{t-1}k^{t-j}c_{j}
\end{align}
Taking the absolute value and applying the given condition \( |c_j| \le q|a_j| \), we have:
\begin{align}
    |e_{t}| \le \sum_{j=0}^{t-1}k^{t-j}|c_{j}| \le q\sum_{j=0}^{t-1}k^{t-j}|a_{j}|
\end{align}
Since \( a_0=0 \), the sum starts from \( j=1 \). The state \( |a_j| \) can be bounded from its own recurrence \( |a_{t}| \le k(1+q)|a_{t-1}| + |d_t| \), which for \( a_0=0 \) unrolls to:
\begin{align}
    |a_{j}|\le\sum_{i=1}^{j}(k(1+q))^{j-i}|d_{i}|
\end{align}
Substituting the bound for \( |a_j| \) into the inequality for \( |e_t| \) gives a double summation:
\begin{align}
    |e_{t}|\le q\sum_{j=1}^{t-1}k^{t-j}\left(\sum_{i=1}^{j}(k(1+q))^{j-i}|d_{i}|\right)
\end{align}
By swapping the order of summation and evaluating the inner geometric series, we obtain the final result:
\begin{align}
    |a_{t}-b_{t}| \le \sum_{j=1}^{t-1}\left[(k(1+q))^{t-j}-k^{t-j}\right]|d_{j}|
\end{align}

\label{app:lemma:cauchy}
Let \((g_k)_{k=0}^t\) be a sequence of scalars for any finite \(t \in \mathbb{N}\). Let the weights be terms of two geometric series, \(A_k = a^k\) and \(B_k = b^k\), where \(a, b \in (0, 1)\) are the base ratios.

If the condition \(a^2 < b\) holds, then the ratio of the weighted sum is bounded by a constant derived from the corresponding infinite series:
\begin{align}
    \frac{\sum_{k=0}^{t} a^k |g_k|}{\sqrt{\sum_{k=0}^{t} b^k g_k^2}} \le \sqrt{\frac{1}{1 - a^2/b}} 
\end{align}

Let the numerator be \(N_t = \sum_{k=0}^{t} a^k |g_k|\) and the denominator be \(D_t = \sqrt{\sum_{k=0}^{t} b^k g_k^2}\).

We rewrite the numerator as:
\begin{align}
    N_t = \sum_{k=0}^{t} \left( \frac{a^k}{\sqrt{b^k}} \right) \cdot \left( \sqrt{b^k} |g_k| \right)
\end{align}
Applying the Cauchy-Schwarz inequality to these finite sums, we get:
\begin{align}
    N_t^2 &\le \left( \sum_{k=0}^{t} \left( \frac{a^k}{\sqrt{b^k}} \right)^2 \right) \cdot \left( \sum_{k=0}^{t} \left( \sqrt{b^k} |g_k| \right)^2 \right) \nonumber\\
    &= \left( \sum_{k=0}^{t} \frac{a^{2k}}{b^k} \right) \cdot \left( \sum_{k=0}^{t} b^k g_k^2 \right) \nonumber\\
    &= \left( \sum_{k=0}^{t} \left(\frac{a^2}{b}\right)^k \right) \cdot D_t^2
\end{align}
The first term is a finite geometric series. Since the condition \(a^2 < b\) implies that the ratio \(r = a^2/b\) is positive and less than 1, all terms in the series are positive. Therefore, the finite sum is always less than or equal to the sum of the infinite series:
\begin{align}
    \sum_{k=0}^{t} \left(\frac{a^2}{b}\right)^k \le \sum_{k=0}^{\infty} \left(\frac{a^2}{b}\right)^k = \frac{1}{1 - a^2/b}
\end{align}
Substituting this upper bound back into the inequality for \(N_t^2\), we have:
\begin{align}
    N_t^2 \le \left( \frac{1}{1 - a^2/b} \right) \cdot D_t^2
\end{align}
Taking the square root of both sides gives:
\begin{align}
    N_t \le \sqrt{\frac{1}{1 - a^2/b}} \cdot D_t
\end{align}
Finally, dividing by \(D_t\) yields the desired result for any finite \(t\):
\begin{align}
    \frac{N_t}{D_t} = \frac{\sum_{k=0}^{t} a^k |g_k|}{\sqrt{\sum_{k=0}^{t} b^k g_k^2}} \le \sqrt{\frac{1}{1 - a^2/b}}
\end{align}

Following the proof of Lemma~\ref{app:lemma:cauchy}, we apply the Cauchy-Schwarz inequality to get:
\begin{align}
\left(\sum_{k=0}^{t} A_k |g_k|\right)^2 \le \left( \sum_{k=0}^{t} \frac{A_k^2}{B_k} \right) \cdot \left( \sum_{k=0}^{t} B_k g_k^2 \right). \label{eq:cauchy_applied_lemma4}
\end{align}
This implies that the ratio is bounded by the square root of the first term on the right-hand side. We now focus on bounding the term $\sum_{k=0}^{t} \frac{A_k^2}{B_k}$. First, we express the ratio $\frac{A_k^2}{B_k}$ as:
\begin{align}
\frac{A_k^2}{B_k} &= \frac{(\beta_1^k((1+q_M)^k - 1))^2}{(\beta_2(1-q_V))^k} \nonumber \\
&= \left(\frac{\beta_1^2}{\beta_2(1-q_V)}\right)^k ((1+q_M)^k-1)^2. \label{eq:ak_bk_ratio_lemma4}
\end{align}
To bound the term $((1+q_M)^k-1)^2$, we first establish an inequality for $(1+q_M)^k-1$ using the Mean Value Theorem. Let $f(x) = x^k$. For $q_M > 0$, by the Mean Value Theorem, there exists a $c \in (1, 1+q_M)$ such that:
\begin{align}
\frac{f(1+q_M) - f(1)}{(1+q_M)-1} = f'(c) \implies (1+q_M)^k - 1 = q_M \cdot (k c^{k-1}). \label{eq:mvt_raw_lemma4}
\end{align}
Since $c < 1+q_M$, and for $k \ge 1$, we have $c^{k-1} \le (1+q_M)^{k-1}$. This leads to the inequality:
\begin{align}
(1+q_M)^k - 1 \le k \cdot q_M \cdot (1+q_M)^{k-1}. \label{eq:mvt_inequality_lemma4}
\end{align}
Squaring both sides of \eqref{eq:mvt_inequality_lemma4} gives:
\begin{align}
((1+q_M)^k-1)^2 &\le k^2 q_M^2 (1+q_M)^{2(k-1)} \nonumber \\
&= \frac{k^2 q_M^2}{(1+q_M)^2} (1+q_M)^{2k}. \label{eq:squared_inequality_lemma4}
\end{align}
Substituting this back into \eqref{eq:ak_bk_ratio_lemma4}, and using the definition $r' = \frac{\beta_1^2(1+q_M)^2}{\beta_2(1-q_V)}$, we get:
\begin{align}
\frac{A_k^2}{B_k} &\le \left(\frac{\beta_1^2}{\beta_2(1-q_V)}\right)^k \frac{k^2 q_M^2}{(1+q_M)^2} (1+q_M)^{2k} \nonumber \\
&= \frac{q_M^2}{(1+q_M)^2} k^2 \left(\frac{\beta_1^2(1+q_M)^2}{\beta_2(1-q_V)}\right)^k \nonumber \\
&= \frac{q_M^2}{(1+q_M)^2} k^2 (r')^k. \label{eq:ak_bk_bound_final_lemma4}
\end{align}
Now we sum this term. The condition $r' < 1$ ensures the convergence of the infinite series. We first derive the closed-form expression for $\sum_{k=0}^{\infty} k^2 x^k$ for $|x|<1$. We start with the geometric series:
\begin{align}
\sum_{k=0}^{\infty} x^k = \frac{1}{1-x}. \label{eq:geom_series_lemma4}
\end{align}
Differentiating with respect to $x$ and multiplying by $x$ gives:
\begin{align}
\sum_{k=0}^{\infty} k x^k = x \frac{d}{dx}\left(\frac{1}{1-x}\right) = \frac{x}{(1-x)^2}. \label{eq:k_geom_series_lemma4}
\end{align}
Differentiating one more time and multiplying by $x$ yields:
\begin{align}
\sum_{k=0}^{\infty} k^2 x^k = x \frac{d}{dx}\left(\frac{x}{(1-x)^2}\right) = x \frac{1(1-x)^2 - x(2(1-x)(-1))}{(1-x)^4} = \frac{x(1+x)}{(1-x)^3}. \label{eq:k2_geom_series_lemma4}
\end{align}
Using this result with $x=r'$, we can bound the sum $\sum_{k=0}^{t} \frac{A_k^2}{B_k}$ by extending it to an infinite series:
\begin{align}
\sum_{k=0}^{t} \frac{A_k^2}{B_k} &\le \sum_{k=0}^{\infty} \frac{A_k^2}{B_k} \nonumber \\
&\le \sum_{k=0}^{\infty} \frac{q_M^2}{(1+q_M)^2} k^2 (r')^k \nonumber \\
&= \frac{q_M^2}{(1+q_M)^2} \sum_{k=0}^{\infty} k^2 (r')^k \nonumber \\
&= \frac{q_M^2}{(1+q_M)^2} \frac{r'(1+r')}{(1-r')^3}. \label{eq:sum_bound_final_lemma4}
\end{align}
Finally, taking the square root of \eqref{eq:sum_bound_final_lemma4} and substituting it back into the result from the Cauchy-Schwarz inequality \eqref{eq:cauchy_applied_lemma4} gives the desired bound:
\begin{align}
\frac{\sum_{k=0}^{t} A_k |g_k|}{\sqrt{\sum_{k=0}^{t} B_k g_k^2}} \le \sqrt{\sum_{k=0}^{t} \frac{A_k^2}{B_k}} \le \sqrt{\frac{q_M^2}{(1+q_M)^2} \frac{r'(1+r')}{(1-r')^3}} = q_M \cdot \frac{\sqrt{r'(1+r')}}{(1+q_M)(1-r')^{3/2}}. \label{eq:final_result_lemma4}
\end{align}

\label{lemma:grad_bound}
Let the stochastic gradient be bounded in infinity norm almost surely by $\norm{\nabla f_t(\wb; \gamma)}_\infty \le R - \sqrt{\epsilon}$ for any parameters $\wb$. Let the gradient quantization operator satisfy the relative error model $|Q(z) - z| \le q_G|z|$ for any scalar $z$. The quantized gradient estimator $\hat{\gb_t}$ is defined component-wise for $i \in [d]$ as:
\begin{align}
    \hat{g}_{t,i} = \frac{1}{B}\sum_{j=1}^{B} [\nabla^Q f(\wb_{t-1}^Q; \gamma_{t,j})]_i,
\end{align}
where we use $\nabla^Q f(\cdot)$ as shorthand for $Q(\nabla f(\cdot))$ and $[\cdot]_i$ to denote the i-th component. Then, the infinity norm of the estimator is bounded almost surely:
\begin{align}
    \norm{\hat{\gb_t}}_\infty \le (1+q_G)(R - \sqrt{\epsilon}).
\end{align}
For notational simplicity in subsequent proofs, we will use the slightly looser bound $\norm{\hat{\gb_t}}_\infty \le (1+q_G)R$.

We start from the decomposition of the conditional expectation of $\delta_{t,i}$, which we derived previously:
\begin{align}
\nonumber
    \espt{\delta_{t,i}}&= \mathbb{E}_{\gamma} \left[ \nabla_i^Q f(\wb_{t-1}^Q; \gamma) - \nabla_i f(\wb_{t-1}^Q; \gamma) \right]+\mathbb{E}_{\gamma} \left[ \nabla_i f(\wb_{t-1}^Q; \gamma) - \nabla_i f(\wb_{t-1}; \gamma) \right]\\
    &= \underbrace{\mathbb{E}_{\gamma} \left[ \nabla_i^Q f(\wb_{t-1}^Q; \gamma) - \nabla_i f(\wb_{t-1}^Q; \gamma) \right]}_{\text{Term I: Gradient Quantization Bias}} + \underbrace{\left(\nabla_i F(\wb_{t-1}^Q) - \nabla_i F(\wb_{t-1})\right)}_{\text{Term II: Weight Quantization Bias}}
\end{align}
Using the triangle inequality, we can bound the magnitude as:
\begin{align}
    |\espt{\delta_{t,i}}| \le |\text{Term I}| + |\text{Term II}|.
\end{align}
We bound each term separately.

\textbf{Bounding Term I:}
This term is the expected bias from the (potentially biased) gradient quantization. We first apply Jensen's inequality for absolute values, i.e., $|\mathbb{E}[X]| \le \mathbb{E}[|X|]$:
\begin{align}
    |\text{Term I}| &= \left|\mathbb{E}_{\gamma} \left[ \nabla_i^Q f(\wb_{t-1}^Q; \gamma) - \nabla_i f(\wb_{t-1}^Q; \gamma) \right]\right| \nonumber \\
    &\le \mathbb{E}_{\gamma} \left[ \left|\nabla_i^Q f(\wb_{t-1}^Q; \gamma) - \nabla_i f(\wb_{t-1}^Q; \gamma)\right| \right].
\end{align}
By the relative error model for gradient quantization (Assumption \ref{assump:qe} with factor $q_G$):
\begin{align}
    |\text{Term I}| \le \mathbb{E}_{\gamma} \left[ q_G \left|\nabla_i f(\wb_{t-1}^Q; \gamma)\right| \right] \le q_G R.
\end{align}

\textbf{Bounding Term II:}
This term represents the bias from weight quantization. Using the L-smoothness of $F$ (Assumption \ref{assump:smooth}) and the relative error for weights (Assumption \ref{assump:qe}):
\begin{align}
    |\text{Term II}| = |\nabla_i F(\wb_{t-1}^Q) - \nabla_i F(\wb_{t-1})| \le \norm{\nabla F(\wb_{t-1}^Q) - \nabla F(\wb_{t-1})}_2 \le L q_W \norm{\wb_{t-1}}_2.
\end{align}

\textbf{Combining the Bounds:}
Summing the bounds for Term I and Term II, we arrive at the final result:
\begin{align}
    |\espt{\delta_{t,i}}| \le |\text{Term I}| + |\text{Term II}| \le q_G R  + L q_W \norm{\wb_{t-1}}_2.
\end{align}

