\end{equation}
In particular we have $\tilde{v} - v = r^2 - s^2$. With our new notations, we can rewrite~\eqref{app:eq:left_main_term_lemmaC} as
\begin{align}
\nonumber
    \esp{\mathcal{G} \frac{g+\delta}{\sqrt{\epsilon+v}}} &= \esp{\mathcal{G} \frac{g+\delta}{\sqrt{\epsilon+\tilde{v}}} + \mathcal{G}(g+\delta) \left(\frac{1}{\sqrt{\epsilon+v}} - \frac1{\sqrt{\epsilon+\tilde{v}}}\right)} \\
