\label{lemma:sum_ratio}
Assume we have $0 < \beta_1 < \beta_2 \leq 1$ and a sequence of real numbers $(a_n)_{n\in \NN^*}$. We define for all $n \in \NN^*$:
$$b_n = \sum_{j=1}^n \beta_2^{n - j} a_j^2 \quad \text{and} \quad c_n = \sum_{j=1}^n \beta_1^{n-j} a_j.$$
Then for any $\epsilon > 0$, we have the following inequality:
\begin{equation}
    \label{eq:sum_ratio_combined_lemma7}
    \sum_{j=1}^n \frac{c_j^2}{\epsilon + b_j} \leq
    \frac{1}{(1 - \beta_1)(1 - \beta_1 / \beta_2)} \left(\ln\left(1 + \frac{b_n}{\epsilon}\right) - n\ln(\beta_2)\right).
\end{equation}

First, we use Jensen's inequality on $c_j^2$, noting that $\sum_{l=1}^j \beta_1^{j-l} = \frac{1-\beta_1^j}{1-\beta_1} \leq \frac{1}{1-\beta_1}$, to get:
\begin{align*}
    c_{j}^2 = \left(\sum_{l=1}^j \beta_1^{j - l}a_l\right)^2 \leq \left(\sum_{l=1}^j \beta_1^{j-l}\right) \left(\sum_{l=1}^j \beta_1^{j - l}a_l^2\right) \leq \frac{1}{1 - \beta_1}\sum_{l=1}^j \beta_1^{j - l}a_l^2.
\end{align*}
Dividing by $\epsilon + b_j$ and using the fact that for $l \leq j$, $b_j \geq \beta_2^{j-l}b_l$, which implies $\epsilon + b_j \geq \beta_2^{j-l}(\epsilon + b_l)$, we obtain:
\begin{align}
    \frac{c_{j}^2}{\epsilon + b_{j}} \leq \frac{1}{1 - \beta_1}\sum_{l=1}^j \beta_1^{j - l} \frac{a_l^2}{\epsilon + b_j} \leq \frac{1}{1 - \beta_1}\sum_{l=1}^j \left(\frac{\beta_1}{\beta_2}\right)^{j-l}\frac{a_l^2}{\epsilon + b_l}.
\end{align}
Now, we sum over $j \in [n]$ and swap the order of summation:
\begin{align}
\nonumber
    \sum_{j=1}^n \frac{c_{j}^2}{\epsilon + b_{j}} &\leq  \frac{1}{1 - \beta_1}\sum_{j=1}^n\sum_{l=1}^{j}\left(\frac{\beta_1}{\beta_2}\right)^{j -l} \frac{a_{l}^2}{\epsilon + b_{l}}
    = \frac{1}{1 - \beta_1}\sum_{l=1}^n\frac{a_l^2}{\epsilon + b_l}\sum_{j=l}^{n}\left(\frac{\beta_1}{\beta_2}\right)^{j -l} \\
    &\leq \frac{1}{(1 - \beta_1)(1 - \beta_1 /\beta_2)}\sum_{l=1}^n\frac{a_l^2}{\epsilon + b_l}, \label{eq:intermediate_bound_lemma7}
\end{align}
where the last step uses the sum of a geometric series, since $\beta_1/\beta_2 < 1$.

The next step is to bound the final sum. Let's denote $x_l = a_l^2$. The sum is $\sum_{l=1}^n \frac{x_l}{\epsilon + b_l}$, where $b_l = \sum_{k=1}^l \beta_2^{l-k}x_k$. Note that $b_l - x_l = \beta_2 b_{l-1}$ (with $b_0=0$). Using the inequality $\frac{x}{y} \leq \ln(y) - \ln(y-x)$ for $0 < x < y$, we have:
\begin{align*}
\frac{x_l}{\epsilon + b_l} &\leq \ln(\epsilon + b_l) - \ln(\epsilon + b_l - x_l) \\
&= \ln(\epsilon + b_l) - \ln(\epsilon + \beta_2 b_{l-1}) \\
&= \ln\left(\frac{\epsilon + b_l}{\epsilon + b_{l-1}}\right) + \ln\left(\frac{\epsilon + b_{l-1}}{\epsilon + \beta_2 b_{l-1}}\right).
\end{align*}
Summing from $l=1$ to $n$, the first term forms a telescoping series equal to $\ln(\epsilon + b_n) - \ln(\epsilon) = \ln(1 + b_n/\epsilon)$. For the second term, since $\beta_2 \leq 1$ and $b_{l-1} \geq 0$, we have $\frac{\epsilon + \beta_2 b_{l-1}}{\epsilon + b_{l-1}} \geq \beta_2$, which implies $\ln\left(\frac{\epsilon + b_{l-1}}{\epsilon + \beta_2 b_{l-1}}\right) \leq -\ln(\beta_2)$. Thus, summing over $l$ gives:
\begin{equation}
    \label{eq:special_case_bound_lemma7}
    \sum_{l=1}^n\frac{a_l^2}{\epsilon + b_l} \leq \ln\left(1 + \frac{b_n}{\epsilon}\right) - n\ln(\beta_2).
\end{equation}
This inequality is a useful result in itself, corresponding to the special case where $c_j^2$ is replaced by $a_j^2$ (or equivalently $\beta_1 \to 0$ and $a_j$ is replaced by $a_j^2$).

Finally, substituting the bound from \eqref{eq:special_case_bound_lemma7} into \eqref{eq:intermediate_bound_lemma7} yields the desired result.

\begin{align*}
\frac{x_l}{\epsilon + b_l} &\leq \ln(\epsilon + b_l) - \ln(\epsilon + b_l - x_l) \\
&= \ln(\epsilon + b_l) - \ln(\epsilon + \beta_2 b_{l-1}) \\
&= \ln\left(\frac{\epsilon + b_l}{\epsilon + b_{l-1}}\right) + \ln\left(\frac{\epsilon + b_{l-1}}{\epsilon + \beta_2 b_{l-1}}\right).
\end{align*}

\label{app:lemma:sum_geom_sqrt}
For any scalar $\rho \in (0, 1)$ and any integer $K \in \NN$, the following bound holds for the finite geometric sum:
\begin{equation}
    \label{app:eq:sum_geom_sqrt_lemma8}
    \sum_{k = 0}^{K - 1} \rho^k \sqrt{k + 1}  
    \leq \frac{2}{(1 - \rho)^{3/2}}.
\end{equation}

Let the sum be denoted by $S_K = \sum_{k = 0}^{K - 1} \rho^k \sqrt{k + 1}$. We analyze the term $(1-\rho)S_K$:
\begin{align*}
    (1 - \rho) S_K &= \sum_{k = 0}^{K - 1} \rho^k \sqrt{k+1} - \sum_{j = 1}^K \rho^{j} \sqrt{j} \\
    &= 1 + \sum_{k=1}^{K-1} \rho^k(\sqrt{k+1} - \sqrt{k}) - \rho^K\sqrt{K}.
\end{align*}
By the concavity of the square root function, $\sqrt{k+1} - \sqrt{k} \leq \frac{1}{2\sqrt{k}}$. This implies:
\begin{align*}
    (1 - \rho) S_K &\leq 1 + \sum_{k = 1}^{K- 1} \frac{\rho^{k}}{2 \sqrt{k}} 
    \leq 1 + \int_0^{\infty} \frac{\rho^{t}}{2 \sqrt{t}}\mathrm{d}t.
\end{align*}
The integral is a standard Gaussian integral form which evaluates to $\frac{\sqrt{\pi}}{2 \sqrt{-\ln(\rho)}}$. Using the inequality $-\ln(\rho) \geq 1 - \rho$, we have:
\begin{align*}
    (1 - \rho) S_K \leq 1 + \frac{\sqrt{\pi}}{2 \sqrt{1-\rho}} \leq \frac{2}{\sqrt{1-\rho}}.
\end{align*}
Dividing by $(1-\rho)$ yields the desired result.

\label{app:lemma:sum_geom_32}
For any scalar $\rho \in (0, 1)$ and any integer $K \in \NN$, the following bound holds:
\begin{equation}
    \label{app:eq:sum_geom_32_lemma9}
    \sum_{k = 0}^{K - 1} \rho^k \sqrt{k} (k + 1)
    \leq \frac{4 \rho}{(1 - \rho)^{5/2}}.
\end{equation}

Let the sum be denoted by $S_K = \sum_{k = 0}^{K - 1} \rho^k \sqrt{k} (k + 1)$. We proceed by analyzing $(1-\rho)S_K$:
\begin{align*}
    (1-\rho)S_K &= \sum_{k = 1}^{K - 1} \rho^k \left[ \sqrt{k} (k + 1) - k\sqrt{k - 1}\right] - \rho^K k \sqrt{K-1} \\
    &\leq \sum_{k = 1}^{K - 1} \rho^k (2\sqrt{k}),
\end{align*}
where the inequality holds because $\sqrt{k} (k + 1) - k\sqrt{k - 1} \le 2\sqrt{k}$. Re-indexing the sum gives:
\begin{align*}
    (1 - \rho) S_K &\leq 2 \rho \sum_{k = 1}^{K - 1} \rho^{k-1} \sqrt{k} = 2 \rho \sum_{j = 0}^{K - 2} \rho^j \sqrt{j + 1}.
\end{align*}
Applying the result from Lemma~\ref{app:lemma:sum_geom_sqrt} to the final sum, we get:
\begin{align*}
     (1 - \rho) S_K  \leq 2 \rho \left( \frac{2}{(1 - \rho)^{3/2}} \right) = \frac{4 \rho}{(1 - \rho)^{3/2}}.
\end{align*}
Dividing both sides by $(1-\rho)$ completes the proof.

\label{app:lemma:u}
Under the condition that $\beta_1(1+q_M) < \beta_2(1-q_V)$, the expected sum of squared updates over $T$ iterations is bounded by:
\begin{align}
    \sum_{t=1}^T\esp{\norm{\ub_t}^2_2} &\le \frac{d}{(1 - \beta_1(1+q_M))(1 - \frac{\beta_1(1+q_M)}{\beta_2(1-q_V)})} \nonumber \\ 
    &\quad \times \left(\ln\left(1 + \frac{((1+q_G)R)^2}{\epsilon(1-\beta_2(1-q_V))}\right) - T\ln(\beta_2(1-q_V))\right). \label{app:eq:sum_ratio_u_lemma10}
\end{align}

The proof proceeds by first expanding the term of interest, applying bounds on the moment estimates derived from their recurrence relations, and then leveraging Lemma~\ref{lemma:sum_ratio} to bound the resulting sum.

We begin by expanding the definition of $\norm{\ub_t}_2^2$, separating the sum over the dimension $d$, and taking the expectation:
\begin{align}
    \sum_{t=1}^T\esp{\norm{\ub_t}^2_2} = \sum_{t=1}^T\esp{\sum_{i\in [d]}\frac{m^2_{t,i}}{\epsilon+v_{t,i}}} = \sum_{i\in [d]}\sum_{t=1}^T\esp{\frac{m^2_{t,i}}{\epsilon+v_{t,i}}}.
\end{align}
For each coordinate $i$, we bound the numerator $m_{t,i}^2$ from above and the denominator $\epsilon+v_{t,i}$ from below. By unrolling the recurrence for $m_{t,i}$ and applying the triangle inequality along with the relative error model, we get an upper bound on its magnitude:
\begin{align}
    |m_{t, i}| \le \sum_{k=1}^t\beta_1^{t-k}(1+q_M)^{t-k}|\nabla_i f_k(\wb_{k-1}) + \delta_{k,i}|.
\end{align}
For the denominator, Lemma~\ref{app:lemma:moment_relation} provides a lower bound for $v_{t,i}$:
\begin{align}
    v_{t,i} \ge \sum_{k=1}^t\beta_2^{t-k}(1-q_V)^{t-k}(\nabla_i f_k(\wb_{k-1}) + \delta_{k,i})^2.
\end{align}
Substituting these into the sum gives the inequality:
\begin{align}
 \label{eq:u_bound_intermediate_lemma10}
 \sum_{t=1}^T\esp{\norm{\ub_t}^2_2} \le \sum_{i\in [d]}\sum_{t=1}^T\esp{\frac{\left(\sum_{k=1}^t\beta_1^{t-k}(1+q_M)^{t-k}|\hat{g}_{k,i}|\right)^2}{\epsilon+\sum_{k=1}^t\beta_2^{t-k}(1-q_V)^{t-k}\hat{g}_{k,i}^2}},
\end{align}
where for brevity we denote $\hat{g}_{k,i} = \nabla_i f_k(\wb_{k-1}) + \delta_{k,i}$.

The inner sum over $t$ for each coordinate $i$ in \eqref{eq:u_bound_intermediate_lemma10} perfectly matches the form required by Lemma~\ref{lemma:sum_ratio}. To apply it, we make the following substitutions into the lemma's notation:
\begin{itemize}[leftmargin=*]
    \item Let the sequence $(a_j)_{j\in\NN^*}$ be $a_k = |\hat{g}_{k,i}|$.
    \item Let the effective decay factors be $\beta'_1 = \beta_1(1+q_M)$ and $\beta'_2 = \beta_2(1-q_V)$. The lemma's condition $\beta'_1 < \beta'_2$ is satisfied by our assumption.
\end{itemize}
With these substitutions, the numerator term becomes $\left(\sum_{k=1}^t (\beta'_1)^{t-k} a_k\right)^2 = c_t^2$ and the sum in the denominator becomes $\sum_{k=1}^t (\beta'_2)^{t-k} a_k^2 = b_t$. Applying Lemma~\ref{lemma:sum_ratio} to the sum over $t$ for a fixed $i$ yields:
\begin{align}
\label{eq:u_bound_after_lemma_lemma10}
    \sum_{t=1}^T \esp{\frac{c_t^2}{\epsilon+b_t}} \le \frac{1}{(1 - \beta'_1)(1 - \beta'_1/\beta'_2)} \left( \ln\left(1 + \frac{b_T}{\epsilon}\right) - T\ln(\beta'_2) \right).
\end{align}

The final step is to find an upper bound for $b_T$. By definition:
\begin{align}
    b_T = \sum_{k=1}^T (\beta'_2)^{T-k} a_k^2 = \sum_{k=1}^T (\beta_2(1-q_V))^{T-k} \hat{g}_{k,i}^2.
\end{align}
From Lemma~\ref{lemma:grad_bound}, we have a uniform bound on the quantized gradient estimator, $|\hat{g}_{k,i}| \le (1+q_G)R$. Therefore:
\begin{align}
    b_T &\le \sum_{k=1}^T (\beta_2(1-q_V))^{T-k} ((1+q_G)R)^2 \nonumber \\
    &= ((1+q_G)R)^2 \sum_{j=0}^{T-1} (\beta_2(1-q_V))^{j} \nonumber \\
    &\le ((1+q_G)R)^2 \frac{1}{1 - \beta_2(1-q_V)}.
\end{align}

Substituting the bound for $b_T$ back into \eqref{eq:u_bound_after_lemma_lemma10}, and re-inserting the definitions of $\beta'_1$ and $\beta'_2$, we obtain the bound for a single coordinate $i$. As this bound is identical for all $d$ coordinates, we multiply by $d$ to get the final result stated in \eqref{app:eq:sum_ratio_u_lemma10}. This completes the proof.

\label{lemma:bound_on_M}
The term M, representing the accumulated quantization bias from \eqref{app:eq:common_big_main}, is bounded by:
\begin{align}
    M \le \frac{\eta_T d T}{\sqrt{\epsilon}(1-\beta_1)} \left( q_G R^2 + L q_W R \norm{\wb_0}_2 \right) + \frac{\eta_T^2 d L q_W UR T^2}{2\sqrt{\epsilon}(1-\beta_1)},
\end{align}
where $U = \sqrt{\frac{d}{1-\frac{\beta_1^2(1+q_M)^2}{\beta_2(1-q_V)}}}$.

\begin{align}
    M \le \frac{\eta_T d T}{\sqrt{\epsilon}(1-\beta_1)} \left( q_G R^2 + L q_W R \norm{\wb_0}_2 \right) + \frac{\eta_T^2 d L q_W UR T^2}{2\sqrt{\epsilon}(1-\beta_1)},
\end{align}

First, we establish a uniform bound on the update norm $\norm{\ub_t}_2$ using Lemma~\ref{app:lemma:cauchy}:
\begin{align}
    \norm{\ub_t}_2 &= \sqrt{\sum_{i\in [d]}\frac{m_{t,i}^2}{\epsilon+v_{t,i}}} \nonumber \\
    & \le \sqrt{\sum_{i\in [d]}\frac{(\sum_{k=0}^t\beta_1^{t-k}(1+q_M)^{t-k}|\nabla_i f_k(\wb_{k-1}) + \delta_{k,i}|)^2}{(\sum_{k=0}^t\beta_2^{t-k}(1-q_V)^{t-k}(\nabla_i f_k(\wb_{k-1}) + \delta_{k,i})^2)}} \nonumber \\
    & \le \sqrt{\frac{d}{1-\frac{\beta_1^2(1+q_M)^2}{\beta_2(1-q_V)}}} \triangleq U
\end{align}
Now, let's recall the definition of $M$:
\begin{equation*}
    M = \eta_T d \sum_{t=1}^T \esp{\sum_{k=0}^{t-1} \beta_1^k M_{t-k}}, \quad \text{where} \quad M_{t-k} = \frac{q_G R^2 + L q_W R \norm{\wb_{t-k-1}}_2}{\sqrt{\epsilon}}.
\end{equation*}
We can split $M$ into two components: a constant part $M_{\text{const}}$ and a weight-dependent part $M_{\text{weights}}$.
\begin{align*}
    M_{\text{const}} &= \frac{\eta_T d q_G R^2}{\sqrt{\epsilon}} \sum_{t=1}^T \sum_{k=0}^{t-1} \beta_1^k \\
    M_{\text{weights}} &= \frac{\eta_T d L q_W R}{\sqrt{\epsilon}} \sum_{t=1}^T \sum_{k=0}^{t-1} \beta_1^k \esp{\norm{\wb_{t-k-1}}_2}
\end{align*}
Bounding $M_{\text{const}}$ is straightforward. The inner sum is a geometric series bounded by $\frac{1}{1-\beta_1}$, so the double summation is bounded by $\frac{T}{1-\beta_1}$.
\begin{equation}
    M_{\text{const}} \le \frac{\eta_T d q_G R^2 T}{\sqrt{\epsilon}(1-\beta_1)}.
\end{equation}
The main challenge is to bound $M_{\text{weights}}$. To do this, we first need a bound on the expected weight norm $\esp{\norm{\wb_j}_2}$. From the update rule $\wb_j = \wb_{j-1} - \eta_j \ub_j$, we can unroll the recursion:
\begin{equation*}
    \wb_j = \wb_0 - \sum_{l=1}^j \eta_l \ub_l.
\end{equation*}
Applying the triangle inequality and taking the expectation, we get:
\begin{equation*}
    \esp{\norm{\wb_j}_2} \le \norm{\wb_0}_2 + \esp{\sum_{l=1}^j \eta_l \norm{\ub_l}_2}.
\end{equation*}
Using the uniform bound $\norm{\ub_l}_2 \le U$, we have:
\begin{equation*}
    \esp{\norm{\wb_j}_2} \le \norm{\wb_0}_2 + U \sum_{l=1}^j \eta_l \le \norm{\wb_0}_2+Uj\eta_T .
\end{equation*}

Now we substitute this bound back into the expression for $M_{\text{weights}}$. We first swap the order of summation. Let $j = t-k-1$. For a fixed $j \in \{0, \dots, T-1\}$, the term $\esp{\norm{\wb_j}_2}$ appears when $k=t-j-1$. This is valid for $t$ from $j+1$ to $T$.
\begin{align*}
    \sum_{t=1}^T \sum_{k=0}^{t-1} \beta_1^k \esp{\norm{\wb_{t-k-1}}_2} &= \sum_{j=0}^{T-1} \esp{\norm{\wb_j}_2} \sum_{t=j+1}^{T} \beta_1^{t-j-1} \\
    &= \sum_{j=0}^{T-1} \esp{\norm{\wb_j}_2} \sum_{m=0}^{T-j-1} \beta_1^{m} \\
    &\le  \frac{1}{1-\beta_1} \sum_{j=0}^{T-1} \esp{\norm{\wb_j}_2}.
\end{align*}
Next, we substitute the linear bound:
\begin{align*}
    \frac{1}{1-\beta_1} \sum_{j=0}^{T-1} \esp{\norm{\wb_j}_2} &\le \frac{1}{1-\beta_1} \sum_{j=0}^{T-1} \left( \norm{\wb_0}_2 + j \cdot U \cdot \eta_T \right) \\
    &= \frac{1}{1-\beta_1} \left( T\norm{\wb_0}_2 + U \eta_T \sum_{j=0}^{T-1} j \right).
\end{align*}
The sum of the first $T-1$ integers is $\frac{(T-1)T}{2} < \frac{T^2}{2}$. This gives:
\begin{equation*}
    \le \frac{1}{1-\beta_1} \left( T\norm{\wb_0}_2 + \frac{T^2}{2} U \eta_T \right).
\end{equation*}
Finally, we assemble the complete bound for $M_{\text{weights}}$:
\begin{equation*}
    M_{\text{weights}} \le \frac{\eta_T d L q_W R}{\sqrt{\epsilon}(1-\beta_1)} \left( T\norm{\wb_0}_2 + \frac{T^2}{2} U \eta_T \right).
\end{equation*}
Combining $M_{\text{const}}$ with $M_{\text{weights}}$, we get the final bound for $M$.
\begin{align}
    \label{eq:M_bound_final_linear_full}
    M &\le \frac{\eta_T d T}{\sqrt{\epsilon}(1-\beta_1)} \left( q_G R^2 + L q_W R \norm{\wb_0}_2 \right) + \frac{\eta_T^2 d L q_W UR T^2}{2\sqrt{\epsilon}(1-\beta_1)} \nonumber \\
\end{align}

