    M = \eta_T d \sum_{t=1}^T \esp{\sum_{k=0}^{t-1} \beta_1^k M_{t-k}}, \quad \text{where} \quad M_{t-k} = \frac{q_G R^2 + L q_W R \norm{\wb_{t-k-1}}_2}{\sqrt{\epsilon}}.
\end{equation*}

\begin{align*}
    M_{\text{const}} &= \frac{\eta_T d q_G R^2}{\sqrt{\epsilon}} \sum_{t=1}^T \sum_{k=0}^{t-1} \beta_1^k \\
    M_{\text{weights}} &= \frac{\eta_T d L q_W R}{\sqrt{\epsilon}} \sum_{t=1}^T \sum_{k=0}^{t-1} \beta_1^k \esp{\norm{\wb_{t-k-1}}_2}
\end{align*}

\begin{equation*}
    M_{\text{weights}} \le \frac{\eta_T d L q_W R}{\sqrt{\epsilon}(1-\beta_1)} \left( T\norm{\wb_0}_2 + \frac{T^2}{2} U \eta_T \right).
